<!doctype html>
<html lang="en" data-theme="light">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="theme-color" content="#f7f3f8">
  <meta name="description" content="Discover hair, bridal, skin, nail and beauty education experiences at Vogue Salon & Academy in Tarn Taran, Punjab.">
  <title>Vogue Salon &amp; Academy — Beauty, with attitude.</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root{color-scheme:light;--bg:#f8f5f8;--surface:#fff;--surface-2:#f0eaf2;--ink:#241c29;--muted:#706673;--primary:#6b426d;--on-primary:#fff8ff;--secondary:#745765;--accent:#bd785f;--line:rgba(57,39,60,.14);--nav:rgba(248,245,248,.78);--shadow:0 18px 55px rgba(61,39,66,.11);--radius:28px;--max:1240px;--sans:'DM Sans',sans-serif;--display:'Manrope',sans-serif}
    html[data-theme=dark]{color-scheme:dark;--bg:#171319;--surface:#231e25;--surface-2:#302832;--ink:#f7eff8;--muted:#c2b5c4;--primary:#e2b9e5;--on-primary:#321b35;--secondary:#d7b8c7;--accent:#f0ae91;--line:rgba(255,239,255,.14);--nav:rgba(23,19,25,.8);--shadow:0 18px 55px rgba(0,0,0,.28)}
    *{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:90px}body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);transition:background .25s,color .25s}body,button,a{ -webkit-tap-highlight-color:transparent}a{color:inherit;text-decoration:none}button{font:inherit}img{display:block;max-width:100%}::selection{background:var(--primary);color:var(--on-primary)}.wrap{width:min(var(--max),calc(100% - 48px));margin-inline:auto}.eyebrow{display:inline-flex;align-items:center;gap:10px;font-size:.72rem;font-weight:800;letter-spacing:.17em;text-transform:uppercase;color:var(--primary)}.eyebrow:before{content:"";width:24px;height:2px;border-radius:2px;background:var(--accent)}.display{font-family:var(--display);font-weight:600;letter-spacing:-.075em;line-height:.94}.section-head{max-width:760px;margin-bottom:42px}.section-head h2{font-size:clamp(2.6rem,6.5vw,5.8rem);margin:17px 0 18px}.section-head p{max-width:600px;color:var(--muted);font-size:1.05rem;line-height:1.75}.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;border:1px solid transparent;border-radius:999px;padding:14px 21px;font-size:.92rem;font-weight:800;cursor:pointer;transition:transform .25s,box-shadow .25s,background .25s}.btn:hover{transform:translateY(-3px)}.btn-primary{background:var(--primary);color:var(--on-primary);box-shadow:0 8px 22px color-mix(in srgb,var(--primary) 22%,transparent)}.btn-tonal{background:var(--surface-2);color:var(--ink)}.btn-outline{border-color:var(--line);background:transparent;color:var(--ink)}.icon-btn{display:grid;place-items:center;width:44px;height:44px;border-radius:50%;border:1px solid var(--line);background:var(--surface);color:var(--ink);cursor:pointer}
    .topbar{position:fixed;z-index:30;top:0;left:0;right:0;padding:13px 0;background:var(--nav);backdrop-filter:blur(20px);border-bottom:1px solid var(--line)}.nav{display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{display:flex;align-items:center;gap:11px;min-width:max-content}.brand-mark{display:grid;place-items:center;width:42px;height:42px;border-radius:15px;background:var(--primary);color:var(--on-primary);font-family:var(--display);font-weight:800;letter-spacing:-.1em;font-size:1.1rem}.brand-logo{display:block;flex:0 0 auto;width:52px;height:52px;object-fit:contain;border-radius:8px;background:#fff}.brand-name{font-family:var(--display);font-weight:800;letter-spacing:-.045em;line-height:1.03}.brand-name small{display:block;margin-top:4px;font:700 .57rem var(--sans);letter-spacing:.19em;text-transform:uppercase;color:var(--muted)}.nav-links{display:flex;align-items:center;gap:clamp(14px,2.4vw,32px);font-size:.86rem;font-weight:700;color:var(--muted)}.nav-links a:hover{color:var(--primary)}.nav-actions{display:flex;align-items:center;gap:9px}.nav-book{padding:12px 17px;font-size:.83rem}.menu-toggle{display:none}
    .hero{min-height:100svh;position:relative;display:grid;align-items:center;overflow:hidden;padding:130px 0 74px;isolation:isolate}.hero:before{content:"";position:absolute;z-index:-2;inset:0 0 0 34%;background:linear-gradient(90deg,var(--bg) 0%,transparent 32%),url('https://images.unsplash.com/photo-1560066984-138dadb4c035?auto=format&fit=crop&w=1800&q=88') center 38%/cover;transform:scale(1.08);filter:saturate(.83)}.hero:after{content:"";position:absolute;z-index:-1;inset:0;background:linear-gradient(90deg,var(--bg) 0%,color-mix(in srgb,var(--bg) 94%,transparent) 25%,color-mix(in srgb,var(--bg) 35%,transparent) 72%,color-mix(in srgb,var(--bg) 15%,transparent)),linear-gradient(0deg,var(--bg),transparent 27%)}html[data-theme=dark] .hero:before{filter:saturate(.65) brightness(.6)}.hero-grid{display:grid;grid-template-columns:1.03fr .97fr;align-items:center;gap:30px}.hero-copy{max-width:720px;padding:35px 0}.hero h1{font-size:clamp(4.2rem,9.7vw,9.1rem);margin:24px 0 24px;max-width:780px}.hero h1 em{font-style:normal;color:var(--primary);position:relative}.hero-lead{font-size:clamp(1.02rem,1.4vw,1.2rem);line-height:1.75;color:var(--muted);max-width:490px}.hero-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:30px}.hero-note{display:flex;align-items:center;gap:12px;margin-top:37px;font-size:.82rem;color:var(--muted)}.avatar-stack{display:flex;padding-left:8px}.avatar-stack span{display:grid;place-items:center;width:29px;height:29px;margin-left:-8px;border:2px solid var(--bg);border-radius:50%;background:var(--surface-2);font-size:.7rem;font-weight:800;color:var(--primary)}.hero-visual{min-height:530px;position:relative;perspective:1000px;isolation:isolate}.hero-visual:before{content:"";position:absolute;z-index:-1;width:76%;aspect-ratio:1;left:13%;top:11%;border-radius:50%;background:radial-gradient(circle at 35% 32%,color-mix(in srgb,var(--accent) 78%,white) 0%,color-mix(in srgb,var(--primary) 72%,transparent) 43%,color-mix(in srgb,var(--primary) 12%,transparent) 70%,transparent 72%);filter:blur(2px);opacity:.48;transform:translate3d(0,0,0) scale(.94);animation:hero-orb-drift 9s ease-in-out infinite alternate;pointer-events:none}.hero-visual:after{content:"";position:absolute;z-index:-1;width:62%;aspect-ratio:1;right:-3%;bottom:2%;border:1px solid color-mix(in srgb,var(--primary) 32%,transparent);border-radius:50%;box-shadow:0 0 55px color-mix(in srgb,var(--primary) 13%,transparent),inset 0 0 45px color-mix(in srgb,var(--accent) 10%,transparent);animation:hero-orb-breathe 7s ease-in-out infinite alternate;pointer-events:none}.hero-orb.orb-one{position:absolute;z-index:1;top:7%;left:5%;width:clamp(76px,10vw,128px);aspect-ratio:1;pointer-events:none;background:none;border:0;border-radius:0;box-shadow:none;transform:translate3d(0,0,0) scale(1);animation:hero-orb-float 4.2s ease-in-out infinite alternate;will-change:transform,filter;filter:drop-shadow(0 8px 18px color-mix(in srgb,var(--primary) 24%,transparent))}.hero-orb.orb-one:before{content:"";position:absolute;inset:8%;background:linear-gradient(145deg,#fff4df 4%,color-mix(in srgb,var(--accent) 82%,white) 38%,var(--primary) 82%);clip-path:polygon(50% 0,61% 37%,100% 50%,61% 63%,50% 100%,39% 63%,0 50%,39% 37%);opacity:.94}.hero-orb.orb-one:after{content:"";position:absolute;width:23%;aspect-ratio:1;right:0;top:1%;background:linear-gradient(135deg,#fff8ec,color-mix(in srgb,var(--accent) 76%,white));clip-path:polygon(50% 0,62% 38%,100% 50%,62% 62%,50% 100%,38% 62%,0 50%,38% 38%);filter:drop-shadow(0 0 7px color-mix(in srgb,var(--accent) 48%,transparent))}
    .hero-image{position:absolute;inset:4% 4% 4% 13%;overflow:hidden;border-radius:48% 48% 34px 34px;background:var(--surface-2);box-shadow:var(--shadow);transform:rotateY(-7deg) rotateZ(2deg);will-change:transform}.hero-image img{width:100%;height:100%;object-fit:cover;filter:saturate(.8)}.hero-image:after{content:"";position:absolute;inset:40% 0 0;background:linear-gradient(transparent,rgba(22,12,22,.52))}.float-chip{position:absolute;z-index:2;display:flex;align-items:center;gap:12px;padding:14px 17px;border:1px solid var(--line);border-radius:22px;background:color-mix(in srgb,var(--surface) 86%,transparent);backdrop-filter:blur(16px);box-shadow:var(--shadow)}.float-chip strong{display:block;font-size:.92rem}.float-chip small{display:block;color:var(--muted);font-size:.74rem;margin-top:3px}.float-chip .chip-icon{display:grid;place-items:center;width:42px;height:42px;border-radius:15px;background:var(--surface-2);color:var(--primary);font-size:1.3rem}.chip-top{right:-1%;top:15%}.chip-bottom{left:0;bottom:14%}.hero-image-caption{position:absolute;z-index:2;left:25%;right:12%;bottom:11%;color:#fff}.hero-image-caption span{font-size:.68rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase}.hero-image-caption p{font:600 clamp(1.7rem,3vw,2.8rem)/1.03 var(--display);letter-spacing:-.06em;margin:10px 0 0}
    @keyframes hero-orb-float{0%{transform:translate3d(-10px,5px,0) scale(.92) rotate(-8deg);filter:brightness(.94)}50%{transform:translate3d(8px,-13px,0) scale(1.06) rotate(5deg);filter:brightness(1.12)}100%{transform:translate3d(-3px,10px,0) scale(.98) rotate(12deg);filter:brightness(1)}}@keyframes hero-orb-drift{0%{transform:translate3d(-2%,1%,0) scale(.92);filter:blur(2px)}100%{transform:translate3d(3%,-2%,0) scale(1.06);filter:blur(7px)}}@keyframes hero-orb-breathe{0%{transform:translate3d(0,0,0) scale(.96);opacity:.45}100%{transform:translate3d(-4%,-3%,0) scale(1.04);opacity:.9}}@media(prefers-reduced-motion:reduce){.hero-orb.orb-one,.hero-visual:before,.hero-visual:after{animation:none!important}}
    .ticker{overflow:hidden;border-block:1px solid var(--line);background:var(--surface);padding:18px 0}.ticker-track{display:flex;align-items:center;gap:30px;width:max-content;animation:ticker 32s linear infinite}.ticker span{font-size:.72rem;letter-spacing:.16em;text-transform:uppercase;font-weight:800;color:var(--muted);white-space:nowrap}.ticker b{font-size:1rem;color:var(--accent)}@keyframes ticker{to{transform:translateX(-50%)}}
    .intro{padding:clamp(90px,12vw,155px) 0}.intro-grid{display:grid;grid-template-columns:.8fr 1.2fr;gap:clamp(36px,8vw,120px);align-items:start}.intro-title{font-size:clamp(2.8rem,6vw,5.7rem);margin:17px 0}.intro-title span{color:var(--primary)}.intro-text{font-size:clamp(1.1rem,2vw,1.5rem);line-height:1.65;letter-spacing:-.03em}.intro-text p{margin:0 0 23px}.intro-text .muted{font-size:1rem;line-height:1.8;letter-spacing:0;color:var(--muted)}
    .services{padding:clamp(80px,10vw,130px) 0;background:var(--surface-2);border-radius:42px 42px 0 0}.service-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;perspective:1200px}.service-card{position:relative;min-height:410px;overflow:hidden;border-radius:var(--radius);background:var(--surface);box-shadow:0 3px 12px rgba(0,0,0,.04);transform-style:preserve-3d;will-change:transform}.service-card:nth-child(2){margin-top:42px}.service-card:nth-child(3){margin-top:84px}.service-image{height:260px;overflow:hidden;background:var(--surface-2)}.service-image img{width:100%;height:100%;object-fit:cover;transition:transform .7s cubic-bezier(.2,.7,.2,1)}.service-card:hover .service-image img{transform:scale(1.06)}.service-info{padding:23px 24px 26px}.service-topline{display:flex;align-items:center;justify-content:space-between;gap:10px}.service-num{font-size:.72rem;font-weight:800;letter-spacing:.1em;color:var(--muted)}.service-arrow{display:grid;place-items:center;width:36px;height:36px;border-radius:50%;background:var(--surface-2);color:var(--primary)}.service-info h3{font:700 1.45rem var(--display);letter-spacing:-.05em;margin:14px 0 8px}.service-info p{color:var(--muted);font-size:.9rem;line-height:1.65;margin:0}
    .manifesto{position:relative;overflow:hidden;padding:clamp(105px,15vw,190px) 0;background:#39243b;color:#fff;isolation:isolate}.manifesto:before{content:"";position:absolute;z-index:-1;inset:0;background:linear-gradient(90deg,rgba(35,18,39,.92) 0%,rgba(55,27,54,.82) 58%,rgba(40,20,42,.70) 100%),url("https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=2200&q=88") center 38%/cover no-repeat}.manifesto:after{content:"";position:absolute;z-index:-1;inset:0;background:linear-gradient(0deg,rgba(28,14,30,.32),transparent 65%);pointer-events:none}.manifesto-grid{display:grid;grid-template-columns:.65fr 1.35fr;gap:45px;align-items:start}.manifesto .eyebrow{color:#fff;opacity:.82}.manifesto h2{font-size:clamp(3.3rem,8vw,8rem);margin:0;max-width:950px}.manifesto h2 em{font-style:normal;color:#f0ae91}.manifesto-bottom{display:flex;justify-content:space-between;align-items:end;gap:35px;margin-top:54px}.manifesto-bottom p{max-width:420px;line-height:1.75;opacity:.82}.manifesto .btn{background:#fff;color:#39243b}
    .academy{padding:clamp(90px,12vw,150px) 0}.academy-grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(32px,7vw,100px);align-items:center}.academy-visual{position:relative;min-height:550px;perspective:1000px}.academy-photo{position:absolute;inset:0 10% 6% 0;overflow:hidden;border-radius:34px;background:var(--surface-2);transform:rotateY(5deg)}.academy-photo img{width:100%;height:100%;object-fit:cover}.academy-label{position:absolute;right:0;bottom:0;max-width:245px;padding:23px;border-radius:25px;background:var(--surface);box-shadow:var(--shadow);border:1px solid var(--line)}.academy-label strong{display:block;font:800 1.35rem var(--display);letter-spacing:-.05em}.academy-label p{margin:8px 0 0;font-size:.85rem;line-height:1.6;color:var(--muted)}.academy-copy h2{font-size:clamp(2.8rem,6vw,5.5rem);margin:17px 0 24px}.academy-copy h2 span{color:var(--primary)}.academy-copy>p{color:var(--muted);line-height:1.8}.academy-points{list-style:none;padding:0;margin:28px 0;display:grid;gap:14px}.academy-points li{display:flex;gap:12px;align-items:start;font-weight:700}.check{display:grid;place-items:center;flex:0 0 25px;width:25px;height:25px;border-radius:50%;background:var(--surface-2);color:var(--primary);font-size:.8rem}
    .gallery{padding:clamp(80px,10vw,130px) 0;background:var(--surface-2);border-radius:40px}.gallery-head{display:flex;justify-content:space-between;align-items:end;gap:25px}.gallery-head .section-head{margin-bottom:35px}.gallery-grid{display:grid;grid-template-columns:1.15fr .85fr .85fr;grid-template-rows:220px 220px;gap:15px}.gallery-item{position:relative;overflow:hidden;border-radius:24px;background:var(--surface);isolation:isolate}.gallery-item:first-child{grid-row:span 2}.gallery-item img{width:100%;height:100%;object-fit:cover;transition:transform .7s}.gallery-item:hover img{transform:scale(1.06)}.gallery-item:after{content:"";position:absolute;inset:45% 0 0;background:linear-gradient(transparent,rgba(17,10,18,.6));z-index:0}.gallery-caption{position:absolute;z-index:1;left:20px;right:20px;bottom:18px;color:white;font-weight:800}.gallery-caption small{display:block;margin-bottom:6px;font-size:.65rem;letter-spacing:.14em;text-transform:uppercase;opacity:.8}.gallery-note{margin-top:20px;font-size:.8rem;color:var(--muted);line-height:1.6}
    .visit{padding:clamp(90px,12vw,155px) 0}.visit-card{position:relative;display:grid;grid-template-columns:1fr .8fr;overflow:hidden;border-radius:36px;background:var(--surface);border:1px solid var(--line);box-shadow:var(--shadow)}.visit-copy{padding:clamp(30px,6vw,76px)}.visit-copy h2{font-size:clamp(2.8rem,6vw,5.5rem);margin:18px 0}.visit-copy p{max-width:500px;color:var(--muted);line-height:1.8}.visit-details{display:grid;gap:13px;margin:28px 0}.visit-detail{display:flex;gap:13px;align-items:start}.visit-detail .chip-icon{display:grid;place-items:center;width:43px;height:43px;flex:0 0 43px;border-radius:15px;background:var(--surface-2);color:var(--primary)}.visit-detail strong{display:block;margin:2px 0 4px}.visit-detail span{font-size:.87rem;color:var(--muted);line-height:1.5}.visit-map{position:relative;min-height:450px;background:var(--surface-2)}.visit-map img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover;filter:saturate(.65)}.map-pin{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);display:grid;place-items:center;width:70px;height:70px;border-radius:24px;background:var(--primary);color:var(--on-primary);font-size:1.7rem;box-shadow:0 10px 35px rgba(0,0,0,.22);border:6px solid color-mix(in srgb,var(--surface) 70%,transparent)}.map-link{position:absolute;left:22px;right:22px;bottom:22px;padding:17px 20px;display:flex;justify-content:space-between;align-items:center;gap:15px;border-radius:20px;background:var(--surface);box-shadow:var(--shadow);font-weight:800}.map-link small{display:block;color:var(--muted);font-weight:500;margin-top:4px}
    .footer{padding:40px 0 25px;border-top:1px solid var(--line)}.footer-top{display:flex;justify-content:space-between;gap:35px;flex-wrap:wrap;padding-bottom:34px}.footer-brand p{max-width:300px;color:var(--muted);line-height:1.7;font-size:.88rem}.footer-links{display:flex;gap:clamp(30px,6vw,80px)}.footer-col{display:grid;align-content:start;gap:12px;font-size:.86rem}.footer-col strong{font-size:.72rem;letter-spacing:.13em;text-transform:uppercase;margin-bottom:4px}.footer-col a{color:var(--muted)}.footer-col a:hover{color:var(--primary)}.footer-bottom{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:22px;color:var(--muted);font-size:.77rem}.social-link{display:inline-flex;align-items:center;gap:8px;font-weight:800;color:var(--primary)!important}
    .reveal{opacity:0;transform:translateY(35px)}.reduce-motion .reveal{opacity:1;transform:none}
    @media(max-width:950px){.nav-links{gap:15px}.nav-links a:nth-child(2){display:none}.hero-grid{grid-template-columns:1fr .7fr}.hero-visual{min-height:440px}.service-grid{gap:13px}.service-card{min-height:390px}.service-image{height:220px}.visit-card{grid-template-columns:1fr .7fr}.gallery-grid{grid-template-rows:190px 190px}}
    @media(max-width:700px){.wrap{width:min(var(--max),calc(100% - 32px))}.topbar{padding:9px 0}.brand-mark{width:39px;height:39px}.brand-logo{width:43px;height:43px}.nav-links{display:none;position:absolute;top:62px;left:16px;right:16px;padding:20px;border:1px solid var(--line);border-radius:24px;background:var(--surface);box-shadow:var(--shadow);flex-direction:column;align-items:stretch;gap:19px}.nav-links.open{display:flex}.nav-links a:nth-child(2){display:block}.menu-toggle{display:grid}.nav-book{display:none}.hero{padding:105px 0 55px;min-height:auto}.hero:before{inset:0;background-position:58% center;opacity:.32}.hero:after{background:linear-gradient(90deg,var(--bg),color-mix(in srgb,var(--bg) 65%,transparent)),linear-gradient(0deg,var(--bg),transparent 40%)}.hero-grid{grid-template-columns:1fr}.hero-copy{padding:38px 0 0}.hero h1{font-size:clamp(4rem,17vw,6.5rem);max-width:600px}.hero-visual{min-height:420px;margin-top:8px}.hero-image{inset:0 7% 4% 12%;transform:none}.chip-top{right:0;top:12%}.chip-bottom{left:0;bottom:10%}.hero-image-caption{left:27%;bottom:12%}.hero-note{margin-top:28px}.intro-grid,.manifesto-grid,.academy-grid{grid-template-columns:1fr}.intro{padding:85px 0}.intro-grid{gap:12px}.section-head{margin-bottom:30px}.service-grid{grid-template-columns:1fr;gap:15px}.service-card,.service-card:nth-child(2),.service-card:nth-child(3){margin-top:0;min-height:0}.service-image{height:270px}.manifesto-grid{gap:25px}.manifesto-bottom{align-items:start;flex-direction:column;margin-top:30px;gap:15px}.academy-visual{min-height:420px;order:2}.academy-copy{order:1}.gallery{border-radius:28px;padding:75px 0}.gallery-head{align-items:start;flex-direction:column}.gallery-grid{grid-template-columns:1fr 1fr;grid-template-rows:220px 160px 160px}.gallery-item:first-child{grid-row:span 2}.gallery-item:last-child{grid-column:span 2}.visit-card{grid-template-columns:1fr}.visit-map{min-height:350px;order:-1}.visit-copy{padding:30px 24px}.footer-links{width:100%;justify-content:space-between}.footer-top{gap:20px}}
    @media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}.reveal{opacity:1;transform:none}}
  /* Instagram lookbook */
.instagram-section{padding:clamp(82px,10vw,132px) 0;background:var(--surface);border-radius:42px}
.instagram-heading{display:flex;justify-content:space-between;align-items:end;gap:32px;margin-bottom:36px}
.instagram-heading-copy{max-width:670px}
.instagram-heading h2{font-size:clamp(3rem,7vw,6.6rem);margin:17px 0 18px}
.instagram-heading h2 em{font-style:normal;color:var(--primary)}
.instagram-heading-copy p{max-width:560px;color:var(--muted);font-size:1.02rem;line-height:1.8}
.instagram-follow{display:flex;align-items:center;gap:13px;max-width:100%;padding:14px 18px;border:1px solid var(--line);border-radius:22px;background:var(--bg);box-shadow:var(--shadow);transition:transform .25s,border-color .25s;white-space:nowrap}
.instagram-follow:hover{transform:translateY(-4px);border-color:var(--primary)}
.instagram-mark{display:grid;place-items:center;flex:0 0 44px;width:44px;height:44px;border-radius:15px;background:linear-gradient(135deg,#f9ce34,#ee2a7b 52%,#6228d7);color:white;font-size:1.9rem;line-height:1}
.instagram-follow small{display:block;color:var(--muted);font-size:.7rem;margin-bottom:4px}
.instagram-follow strong{font-size:.9rem;letter-spacing:-.02em}
.instagram-arrow{font-size:1.25rem;color:var(--primary);margin-left:8px}
.instagram-feed{display:grid;grid-template-columns:1.18fr 1fr 1fr;grid-template-rows:clamp(190px,22vw,290px) clamp(190px,22vw,290px);gap:14px}
.instagram-tile{position:relative;display:block;overflow:hidden;min-width:0;min-height:0;border-radius:25px;background:var(--surface-2);isolation:isolate}
.instagram-tile-feature{grid-row:span 2}
.instagram-tile img{width:100%;height:100%;object-fit:cover;transition:transform .75s cubic-bezier(.2,.7,.2,1),filter .5s;filter:saturate(.87)}
.instagram-tile:hover img{transform:scale(1.07);filter:saturate(1.08)}
.instagram-tile:after{content:"";position:absolute;inset:28% 0 0;background:linear-gradient(transparent,rgba(20,10,22,.78));z-index:0;opacity:.92;transition:opacity .25s}
.instagram-tile:hover:after{opacity:1}
.instagram-tile-overlay{position:absolute;z-index:1;left:20px;right:18px;bottom:20px;color:#fff;display:grid;gap:8px;transform:translateY(7px);transition:transform .3s}
.instagram-tile:hover .instagram-tile-overlay{transform:translateY(0)}
.instagram-tile-overlay small{font-size:.64rem;letter-spacing:.17em;font-weight:800}
.instagram-tile-overlay strong{font:750 clamp(1.05rem,2vw,1.65rem)/1.12 var(--display);letter-spacing:-.045em}
.instagram-tile-overlay b{font-size:.78rem;margin-top:4px}
.instagram-type{position:absolute;z-index:2;top:14px;right:14px;display:grid;place-items:center;width:36px;height:36px;border-radius:13px;background:rgba(255,255,255,.86);color:#6b426d;font-size:1.45rem;backdrop-filter:blur(12px)}
.instagram-bottom{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-top:23px;color:var(--muted);font-size:.82rem}
.instagram-bottom>span{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.instagram-bottom i{width:8px;height:8px;border-radius:50%;background:#4f9b70;box-shadow:0 0 0 4px color-mix(in srgb,#4f9b70 15%,transparent)}
.instagram-bottom strong{color:var(--ink)}
.instagram-bottom>a{color:var(--primary);font-weight:800;white-space:nowrap}
.instagram-disclaimer{font-size:.75rem!important;opacity:.85}
.instagram-gallery-section{margin-bottom:clamp(65px,9vw,110px)}
.instagram-gallery-intro{display:flex;align-items:end;justify-content:space-between;gap:28px;margin-bottom:28px}
.instagram-gallery-intro>div{max-width:700px}
.instagram-gallery-intro .section-heading{margin-bottom:12px}
.instagram-gallery-intro .section-lead{margin-bottom:0}
.instagram-gallery-intro .button{white-space:nowrap}
.instagram-feed-page{grid-template-rows:clamp(220px,27vw,340px) clamp(220px,27vw,340px)}
@media(max-width:800px){.instagram-heading{align-items:start;flex-direction:column}.instagram-follow{align-self:flex-start}.instagram-feed{grid-template-rows:220px 180px}.instagram-gallery-intro{align-items:start;flex-direction:column}}
@media(max-width:600px){.instagram-section{border-radius:28px;padding:75px 0}.instagram-feed,.instagram-feed-page{grid-template-columns:1fr 1fr;grid-template-rows:230px 160px 160px;gap:10px}.instagram-tile-feature{grid-row:span 2}.instagram-tile:last-child{grid-column:span 2}.instagram-tile{border-radius:19px}.instagram-tile-overlay{left:13px;right:12px;bottom:13px;gap:6px}.instagram-tile-overlay strong{font-size:1.05rem}.instagram-tile-overlay b{font-size:.7rem}.instagram-type{top:9px;right:9px;width:30px;height:30px;border-radius:10px}.instagram-bottom{align-items:start;flex-direction:column}.instagram-follow{padding:12px 13px;gap:10px}.instagram-follow strong{font-size:.78rem}.instagram-mark{width:39px;height:39px;flex-basis:39px}.instagram-gallery-intro .button{white-space:normal}}

  
.instagram-feed-live{grid-template-rows:auto;grid-auto-rows:auto;align-items:start}.instagram-feed-live .instagram-embed-card{width:100%;max-width:540px;min-width:0;justify-self:center}.instagram-feed-live .instagram-media{width:100%!important;min-width:0!important}
@media(max-width:600px){.instagram-feed-live{grid-template-columns:minmax(0,1fr);grid-template-rows:auto;gap:18px}.instagram-feed-live .instagram-embed-card{max-width:540px}}

